gIL(){return"\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0645\u062c\u062f\u062f\u064b\u0627"},
gIK(){return"\u0627\u0643\u062a\u0628 \u0627\u0633\u0645\u0643 \u0627\u0644\u0623\u0648\u0644 \u0623\u0648 \u0643\u0646\u064a\u062a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629."},
