gOi(){return"\u062a\u0645\u0651 \u0625\u0646\u0634\u0627\u0621 \u0639\u0627\u0645\u0644 \u0644\u0643\u0646\u0651\u0647 \u0644\u0645 \u064a\u064f\u0648\u062b\u0651\u0642 \u0642\u0637\u0651. \u0623\u062f\u062e\u0644 \u0627\u0644\u0631\u0645\u0632 \u0645\u0646 \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0644\u0625\u0643\u0645\u0627\u0644\u0647\u060c \u0623\u0648 \u0623\u0632\u0644\u0647 \u0648\u0627\u0628\u062f\u0623 \u0645\u0646 \u062c\u062f\u064a\u062f."},
gOf(){return"\u0625\u0643\u0645\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f"},
gOk(){return"\u0625\u0632\u0627\u0644\u0629 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u063a\u064a\u0631 \u0627\u0644\u0645\u0643\u062a\u0645\u0644"},
gOn(){return"\u062a\u0645\u062a \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0639\u0627\u0645\u0644"},
gA4(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0639\u0627\u0645\u0644 \u062b\u0627\u0646\u064d"},
gOh(){return"\u0628\u062f\u0648\u0646 \u0639\u0627\u0645\u0644 \u062b\u0627\u0646\u064d\u060c \u064a\u0631\u0641\u0636 \u0627\u0644\u062e\u0627\u062f\u0645 \u0643\u0644 \u0642\u0631\u0627\u0631 \u0628\u0641\u062a\u062d \u0627\u0644\u0623\u062f\u0644\u0629 \u0627\u0644\u0645\u062e\u062a\u0648\u0645\u0629. \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u064a\u0633\u062a\u063a\u0631\u0642 \u062f\u0642\u064a\u0642\u0629 \u0648\u062a\u0637\u0628\u064a\u0642 \u0645\u0635\u0627\u062f\u0642\u0629."},
