gOe(){return"\u0623\u0636\u0641 \u0647\u0630\u0627 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0625\u0644\u0649 \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0644\u062f\u064a\u0643"},
gOg(){return"\u0644\u0627 \u064a\u0639\u0631\u0636 \u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0631\u0645\u0632 QR: \u0627\u0646\u0633\u062e \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0623\u062f\u0646\u0627\u0647 \u0648\u0623\u0636\u0641\u0647 \u064a\u062f\u0648\u064a\u064b\u0627 \u0641\u064a \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 (Google Authenticator\u060c FreeOTP\u060c Authy\u2026)\u060c \u062b\u0645 \u0623\u062f\u062e\u0644 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u0643\u0648\u0651\u0646 \u0645\u0646 6 \u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0630\u064a \u064a\u0639\u0631\u0636\u0647."},
gOo(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a"},
gOs(){return"\u0639\u0646\u0648\u0627\u0646 otpauth"},
gO9(){return"\u0646\u0633\u062e"},
gA3(){return"\u062a\u0645\u0651 \u0627\u0644\u0646\u0633\u062e"},
guX(){return"\u0631\u0645\u0632 \u0645\u0646 6 \u0623\u0631\u0642\u0627\u0645"},
gA2(){return"\u0623\u062f\u062e\u0644 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0633\u062a\u0629 \u0627\u0644\u062a\u064a \u064a\u0639\u0631\u0636\u0647\u0627 \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0644\u062f\u064a\u0643."},
