gKz(){return"\u062a\u0645\u0651 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0642\u0631\u0627\u0631\u060c \u0644\u0643\u0646 \u0644\u0645 \u064a\u064f\u0641\u062a\u062d \u0623\u064a \u062e\u062a\u0645:"},
guJ(){return"\u0635\u0646\u062f\u0648\u0642\u064a"},
gzi(){return"\u0627\u0644\u0645\u0644\u0641\u0627\u062a \u0648\u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0648\u062c\u0651\u0647\u0629 \u0625\u0644\u064a\u0651"},
gMR(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0623\u064a \u062d\u062f\u062b \u0641\u064a \u0635\u0646\u062f\u0648\u0642\u0643."},
gMS(){return"\u062a\u0638\u0647\u0631 \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0647\u0646\u0627 \u0628\u0645\u062c\u0631\u062f \u0648\u0635\u0648\u0644 \u0645\u0644\u0641 \u0625\u0644\u0649 \u062f\u0627\u0626\u0631\u062a\u0643. \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0641\u0627\u0631\u063a \u064a\u0639\u0646\u064a \u0623\u064a\u0636\u064b\u0627 \u0623\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0628\u062f\u0648\u0646 \u0628\u0637\u0627\u0642\u0629 \u0639\u0648\u0646 \u0646\u0634\u0637\u0629 \u0644\u0627 \u064a\u062a\u0644\u0642\u0651\u0649 \u0634\u064a\u0626\u064b\u0627."},
gMT(){return"\u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d"},
