gMQ(){return"\u062a\u0645\u0651\u062a \u0642\u0631\u0627\u0621\u0629 \u0643\u0644 \u0634\u064a\u0621"},
gMU(){return"\u062a\u0639\u0644\u064a\u0645 \u0643\u0645\u0642\u0631\u0648\u0621"},
gMX(){return"\u0645\u0642\u0631\u0648\u0621"},
gzh(){return"\u062a\u0645\u0651 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0643\u0645\u0642\u0631\u0648\u0621"},
