gN_(){return"\u062a\u0645\u0651 \u062a\u0635\u0639\u064a\u062f \u0627\u0644\u0645\u0644\u0641 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627"},
gN7(){return"\u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0645\u062d\u062c\u0648\u0628"},
