N9(a){return"\u062d\u062f\u062b \u0645\u0624\u0633\u0633\u064a ("+a+")"},
gNb(){return"\u0645\u0639\u0644\u0648\u0645\u0629"},
gNa(){return"\u0645\u0647\u0645"},
gNc(){return"\u0639\u0627\u062c\u0644"},
gCg(){return"\u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632"},
gCe(){return"\u0646\u0642\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u062a\u0643\u0641\u064a \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u062f\u0648\u0646 \u0643\u062a\u0627\u0628\u0629 \u0623\u064a \u0634\u064a\u0621. \u0644\u0630\u0644\u0643 \u064a\u0645\u0643\u0646 \u0644\u0623\u064a \u0634\u062e\u0635 \u064a\u0633\u062a\u0637\u064a\u0639 \u0641\u062a\u062d \u0642\u0641\u0644 \u0647\u0630\u0627 \u0627\u0644\u0647\u0627\u062a\u0641 \u0623\u0646 \u064a\u0641\u062a\u062d \u0647\u0630\u0647 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0642\u0636\u0627\u0626\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u062a\u064a\u062d\u0647\u0627."},
C8(a){return"\u0622\u062e\u0631 \u0627\u062a\u0635\u0627\u0644: "+a},
gtd(){return"\u0646\u0633\u064a\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628"},
C6(a){return"\u0646\u0633\u064a\u0627\u0646 "+a+"\u061f \u0633\u062a\u064f\u0645\u062d\u0649 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0645\u0646 \u0627\u0644\u062e\u0632\u0646\u0629 \u0627\u0644\u0645\u0634\u0641\u0651\u0631\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u0648\u0633\u064a\u0644\u0632\u0645 \u0625\u062f\u062e\u0627\u0644\u0647\u0627 \u0645\u0646 \u062c\u062f\u064a\u062f \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644."},
gC7(){return"\u062a\u0645 \u0646\u0633\u064a\u0627\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632"},
gvJ(){return"\u0646\u0633\u064a\u0627\u0646 \u0643\u0644 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a"},
gCd(){return"\u0647\u0644 \u062a\u0631\u064a\u062f \u0645\u062d\u0648 \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629 \u0645\u0646 \u062e\u0632\u0646\u0629 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632\u061f \u0633\u064a\u0644\u0632\u0645 \u0625\u062f\u062e\u0627\u0644 \u0643\u0644 \u0628\u0631\u064a\u062f \u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0648\u0643\u0644 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0645\u0646 \u062c\u062f\u064a\u062f."},
gCc(){return"\u062a\u0645 \u0645\u062d\u0648 \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632"},
gCf(){return"\u062a\u0639\u0630\u0651\u0631 \u062d\u0641\u0638 \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628: \u0627\u0644\u062e\u0632\u0646\u0629 \u0627\u0644\u0645\u0634\u0641\u0651\u0631\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629. \u0644\u0645 \u064a\u064f\u062d\u0641\u0638 \u0623\u064a \u0634\u064a\u0621 \u2014 \u0648\u0644\u0627 \u062a\u064f\u0643\u062a\u0628 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0623\u0628\u062f\u064b\u0627 \u0628\u0646\u0635 \u0648\u0627\u0636\u062d."},
gC9(){return"\u0644\u0645 \u062a\u0639\u062f \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u064a \u062e\u0632\u0646\u0629 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632."},
gCb(){return"\u062a\u0639\u0630\u0651\u0631 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0628\u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0645\u062d\u0641\u0648\u0638"},
gCa(){return"\u0631\u064f\u0641\u0636\u062a \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629. \u0631\u0628\u0645\u0627 \u062a\u063a\u064a\u0651\u0631\u062a \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0623\u0648 \u0639\u064f\u0637\u0650\u0651\u0644 \u0627\u0644\u062d\u0633\u0627\u0628. \u0646\u064f\u0642\u0644 \u0627\u0644\u0628\u0631\u064a\u062f \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0625\u0644\u0649 \u0627\u0644\u0646\u0645\u0648\u0630\u062c: \u0623\u062f\u062e\u0644 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062d\u0627\u0644\u064a\u0629 \u0623\u0648 \u0627\u0646\u0633\u064e \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628."},
gR1(){return"\u062d\u0641\u0638 \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632"},
gB1(){return"\u0633\u062a\u064f\u062d\u0641\u0638 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0641\u064a \u0627\u0644\u062e\u0632\u0646\u0629 \u0627\u0644\u0645\u0634\u0641\u0651\u0631\u0629 \u0644\u0644\u0647\u0627\u062a\u0641. \u0639\u0646\u062f\u0626\u0630\u064d \u064a\u0633\u062a\u0637\u064a\u0639 \u0623\u064a \u0634\u062e\u0635 \u064a\u0641\u062a\u062d \u0642\u0641\u0644 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0625\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u0627\u0637\u0644\u0627\u0639 \u0639\u0644\u0649 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0642\u0636\u0627\u0626\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u062a\u064a\u062d\u0647\u0627."},
